questionvariables.text:
/* Design: coordinates of the vertices of a cuboid placed away from the origin. Source: adapted from SMP GCSE Foundation 2, Chapter 23, A3, and SMP AS/A2 Core 4, Chapter 9, C2. */
ctx: rand(3);
L: rand([3,4,5,6]); W: rand_with_prohib(2,6,[L]); H: rand_with_prohib(1,4,[L,W]);
x0: rand_with_prohib(-3,3,[0]); y0: rand(4); z0: 1+rand(3);
ta: [x0+L, y0+W, z0+H]; tb: [x0, y0+W, z0+H];
da1: [L,W,H]; da2: [x0+W, y0+L, z0+H];
db1: [x0+W, y0, z0+H]; db2: [0, W, H];
tw1: ta+[1,0,0]; tw2: tb+[1,0,0];
